package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonStreamContext;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class FilteringParserDelegate__nextToken2_TriageGen1Test {

    private JsonParser mockDelegate;
    private TokenFilter mockFilter;
    private TokenFilterContext mockContext;
    private FilteringParserDelegate delegate;

    // Accessing protected method via reflection since it's protected in the target class
    private Method nextToken2Method;

    @Before
    public void setUp() throws Exception {
        mockDelegate = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        mockContext = mock(TokenFilterContext.class);

        // FilteringParserDelegate is protected/final, we instantiate it.
        // Constructor: public FilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches);
        delegate = new FilteringParserDelegate(mockDelegate, mockFilter, true, true);

        nextToken2Method = FilteringParserDelegate.class.getDeclaredMethod("_nextToken2");
        nextToken2Method.setAccessible(true);

        // Inject mock context into the delegate's _headContext field via reflection
        Field headContextField = FilteringParserDelegate.class.getDeclaredField("_headContext");
        headContextField.setAccessible(true);
        headContextField.set(delegate, mockContext);

        // Inject mock itemFilter
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, mockFilter);
    }

    private JsonToken invokeNextToken2() throws Exception {
        return (JsonToken) nextToken2Method.invoke(delegate);
    }

    @Test
    public void testNextToken_NullReturn() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(null);
        assertNull(invokeNextToken2());
    }

    @Test
    public void testStartArray_IncludeAll() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        when(mockFilter.equals(TokenFilter.INCLUDE_ALL)).thenReturn(true);
        // Note: TokenFilter.INCLUDE_ALL is a constant, usually we can't mock equality 
        // but the code checks f == TokenFilter.INCLUDE_ALL. 
        // If f is INCLUDE_ALL, it returns immediately.

        // To trigger the first block, we need the itemFilter to be INCLUDE_ALL
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, TokenFilter.INCLUDE_ALL);

        when(mockContext.createChildArrayContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockContext);

        assertEquals(JsonToken.START_ARRAY, invokeNextToken2());
        verify(mockContext).createChildArrayContext(TokenFilter.INCLUDE_ALL, true);
    }

    @Test
    public void testStartArray_FilterNull_SkipChildren() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, null);

        assertEquals(JsonToken.START_ARRAY, invokeNextToken2()); // Loop continues, next token is needed
        // Since we are in a while(true), we need to mock the next call to break or return
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        when(mockDelegate.getCurrentName()).thenReturn("test");
        // This is a complex loop, we simulate the 'continue' by providing a second token

        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testStartArray_CheckValueReturnsNull() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, mockFilter);

        when(mockContext.checkValue(mockFilter)).thenReturn(null);

        invokeNextToken2();
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testStartObject_IncludeAll() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, TokenFilter.INCLUDE_ALL);

        when(mockContext.createChildObjectContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockContext);

        assertEquals(JsonToken.START_OBJECT, invokeNextToken2());
    }

    @Test
    public void testEndArray_ReturnEnd() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_ARRAY);
        when(mockContext.isStartHandled()).thenReturn(true);
        when(mockContext.getFilter()).thenReturn(mockFilter);
        when(mockContext.getParent()).thenReturn(mockContext);

        assertEquals(JsonToken.END_ARRAY, invokeNextToken2());
        verify(mockFilter).filterFinishArray();
    }

    @Test
    public void testEndObject_NotReturnEnd() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_OBJECT);
        when(mockContext.isStartHandled()).thenReturn(false);
        when(mockContext.getFilter()).thenReturn(null);
        when(mockContext.getParent()).thenReturn(mockContext);

        // Because isStartHandled is false, it continues the loop.
        // We mock the next token to be a value to exit.
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        when(mockDelegate.getCurrentName()).thenReturn("name");
        when(mockContext.setFieldName("name")).thenReturn(TokenFilter.INCLUDE_ALL);

        invokeNextToken2();
        verify(mockContext).getParent();
    }

    @Test
    public void testFieldName_IncludeAll() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("myField");
        when(mockContext.setFieldName("myField")).thenReturn(TokenFilter.INCLUDE_ALL);

        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.FIELD_NAME, invokeNextToken2());
    }

    @Test
    public void testFieldName_FilterOutValue() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("hidden");
        when(mockContext.setFieldName("hidden")).thenReturn(mockFilter);
        when(mockFilter.includeProperty("hidden")).thenReturn(null);

        // Mocking the sequence to avoid infinite loop: FIELD_NAME (filtered) -> VALUE_STRING (return)
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);

        invokeNextToken2();
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testScalarValue_IncludeAll() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_NUMBER_INT, invokeNextToken2());
    }

    @Test
    public void testScalarValue_CheckValueIncludes() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, mockFilter);

        when(mockContext.checkValue(mockFilter)).thenReturn(TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_STRING, invokeNextToken2());
    }

    @Test
    public void testScalarValue_CheckValueNotIncluded() throws Exception {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        Field itemFilterField = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
        itemFilterField.setAccessible(true);
        itemFilterField.set(delegate, mockFilter);

        when(mockContext.checkValue(mockFilter)).thenReturn(mockFilter);
        when(mockFilter.includeValue(mockDelegate)).thenReturn(false);

        // To break the infinite loop when scalar is not included (it hits 'break' in while(true))
        // The loop continues, so we need the next token to be something that returns.
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        when(mockDelegate.getCurrentName()).thenReturn("num");
        when(mockContext.setFieldName("num")).thenReturn(TokenFilter.INCLUDE_ALL);

        invokeNextToken2();
        verify(mockContext).checkValue(mockFilter);
    }
}
